import os
import sys
import json
import logging
from pathlib import Path
from config import ensure_directories

# Importing from utils as per API surface
from utils import read_json, write_json

# Importing specific loaders from the API surface if they existed, 
# but since the surface lists 'run_final_report' functions, we implement the logic here
# to load the specific files generated by T019, T021, T029, T030.
# The API surface lists: load_model_report, load_robustness_report, etc.
# We will define these helper functions here to match the surface requirements.

def load_model_report():
    path = Path("data/results/model_report.json")
    if not path.exists():
        raise FileNotFoundError(f"Required file missing: {path}")
    return read_json(path)

def load_robustness_report():
    path = Path("data/results/robustness_report.json")
    if not path.exists():
        raise FileNotFoundError(f"Required file missing: {path}")
    return read_json(path)

def load_diagnostics():
    path = Path("data/results/diagnostics.json")
    if not path.exists():
        raise FileNotFoundError(f"Required file missing: {path}")
    return read_json(path)

def load_delta_r2():
    path = Path("data/results/delta_r2.json")
    if not path.exists():
        raise FileNotFoundError(f"Required file missing: {path}")
    return read_json(path)

def load_null_distribution():
    path = Path("data/results/null_distribution.json")
    if not path.exists():
        raise FileNotFoundError(f"Required file missing: {path}")
    return read_json(path)

def load_full_model():
    path = Path("data/results/full_model.json")
    if not path.exists():
        raise FileNotFoundError(f"Required file missing: {path}")
    return read_json(path)

def evaluate_success_criteria(model_report, robustness_report, null_dist, full_model):
    """
    Evaluates SC-001 to SC-005 based on the task description.
    Returns a criteria_status object.
    """
    criteria_status = {}

    # Extract metrics
    # From T021 (Null Distribution): p-value
    # The null distribution JSON typically contains the list of null stats.
    # We assume the p-value was calculated in T022/T025 and stored in model_report or we calculate it here.
    # T021 says: "Write the resulting MAE and R2 values to data/results/null_distribution.json".
    # T022 says: "calculate empirical p-value... Output: Log data/logs/power_analysis.log" (Wait, T022 description says log, but T025 says model_report contains p-value).
    # T025 says: "Generate model_report.json containing ... p-value".
    # So we read p-value from model_report.
    
    p_value = model_report.get("p_value")
    correlation_coefficient = model_report.get("Pearson_r") # T019 output
    mae = full_model.get("MAE")
    r_squared = full_model.get("R2")
    
    # Robustness metrics
    # T029: variance metric analysis (r_var)
    # T030: partial correlation
    robustness = robustness_report.get("variance_metric_analysis", {})
    r_var = robustness.get("correlation_coefficient")
    
    # T030 partial correlation p-value
    partial_corr = robustness_report.get("partial_correlation_analysis", {})
    partial_corr_p = partial_corr.get("p_value")

    # SC-001: Primary Association (p < 0.05)
    # Assuming this refers to the main model p-value from T021/T025
    sc001_met = p_value is not None and p_value < 0.05
    criteria_status["SC-001"] = {
        "status": "met" if sc001_met else "not met",
        "narrative_summary": f"Significant: p={p_value:.4f}" if sc001_met else f"Null Finding: p={p_value:.4f}, no evidence of association",
        "metrics": {
            "p_value": p_value
        }
    }

    # SC-002: Null Model Performance (p < 0.05 for the null test? Or that null is near zero?)
    # Task says: "SC-001/002: p < 0.05". Likely SC-002 is the same p-value or a secondary check.
    # Given the context, we map SC-002 to the same p-value or the specific null test result.
    # We will treat SC-002 as the confirmation of the p-value significance.
    sc002_met = p_value is not None and p_value < 0.05
    criteria_status["SC-002"] = {
        "status": "met" if sc002_met else "not met",
        "narrative_summary": f"Null distribution test significant: p={p_value:.4f}" if sc002_met else f"Null distribution test not significant: p={p_value:.4f}",
        "metrics": {
            "p_value": p_value
        }
    }

    # SC-003: Stability of metric (|r_var - r_sd| <= 0.05)
    if r_var is not None and correlation_coefficient is not None:
        diff = abs(r_var - correlation_coefficient)
        sc003_met = diff <= 0.05
        criteria_status["SC-003"] = {
            "status": "met" if sc003_met else "not met",
            "narrative_summary": f"Variance metric stable: |{r_var:.4f} - {correlation_coefficient:.4f}| = {diff:.4f} <= 0.05" if sc003_met else f"Variance metric unstable: difference {diff:.4f} > 0.05",
            "metrics": {
                "correlation_coefficient": correlation_coefficient,
                "r_variance": r_var,
                "difference": diff
            }
        }
    else:
        criteria_status["SC-003"] = {
            "status": "not met",
            "narrative_summary": "Missing data for variance metric comparison",
            "metrics": {}
        }

    # SC-004: MAE variation < 10% (from alpha sweep)
    # T028: alpha sweep. robustness_report should have alpha_sweep results.
    alpha_sweep = robustness_report.get("alpha_sweep", {})
    mae_values = alpha_sweep.get("mae_values", [])
    if mae_values and len(mae_values) > 1:
        mae_min = min(mae_values)
        mae_max = max(mae_values)
        mae_variation = (mae_max - mae_min) / mae_min if mae_min > 0 else 0.0
        sc004_met = mae_variation < 0.10
        criteria_status["SC-004"] = {
            "status": "met" if sc004_met else "not met",
            "narrative_summary": f"MAE stable: variation {mae_variation*100:.2f}% < 10%" if sc004_met else f"MAE unstable: variation {mae_variation*100:.2f}% >= 10%",
            "metrics": {
                "mae": mae,
                "mae_variation_percent": mae_variation * 100,
                "mae_min": mae_min,
                "mae_max": mae_max
            }
        }
    else:
        criteria_status["SC-004"] = {
            "status": "not met",
            "narrative_summary": "Missing alpha sweep data for MAE variation check",
            "metrics": {}
        }

    # SC-005: Partial correlation p < 0.05
    sc005_met = partial_corr_p is not None and partial_corr_p < 0.05
    criteria_status["SC-005"] = {
        "status": "met" if sc005_met else "not met",
        "narrative_summary": f"Partial correlation significant: p={partial_corr_p:.4f}" if sc005_met else f"Partial correlation not significant: p={partial_corr_p:.4f}",
        "metrics": {
            "p_value": partial_corr_p
        }
    }

    return criteria_status

def aggregate_results():
    """
    Regenerates final_report.json with criteria_status object.
    """
    logger = logging.getLogger(__name__)
    logger.info("Starting final report aggregation and criteria evaluation.")

    # Load dependencies
    model_report = load_model_report()
    robustness_report = load_robustness_report()
    null_dist = load_null_distribution()
    full_model = load_full_model()

    # Evaluate criteria
    criteria_status = evaluate_success_criteria(model_report, robustness_report, null_dist, full_model)

    # Construct the new final report
    # T034a created a base final_report.json. T034b says "Regenerate ... with criteria_status object".
    # We will load T034a's output if it exists, or construct a new one, then add criteria_status.
    final_report_path = Path("data/results/final_report.json")
    
    # Try to load existing T034a output to preserve other fields
    if final_report_path.exists():
        final_report = read_json(final_report_path)
    else:
        final_report = {
            "primary_model": model_report,
            "null_distribution": null_dist,
            "robustness": robustness_report
        }
    
    # Add the criteria_status object
    final_report["criteria_status"] = criteria_status

    # Write the final report
    ensure_directories()
    write_json(final_report_path, final_report)
    logger.info(f"Final report written to {final_report_path}")
    logger.info(f"Criteria Status: {json.dumps(criteria_status, indent=2)}")

    return final_report

def main():
    logging.basicConfig(level=logging.INFO)
    ensure_directories()
    aggregate_results()

if __name__ == "__main__":
    main()
